void spmm(std::vector<COOElement> const& A, std::vector<COOElement> const& X, std::vector<double> &Y, size_t M, size_t K, size_t N) {
   std::unordered_map<size_t, std::unordered_map<size_t, double>> cache;

   for (const auto& a : A) {
      cache[a.row][a.column] = a.value;
   }

   Y.assign(M * N, 0);

   for (const auto& x : X) {
      if (cache.count(x.row)) {
         for (const auto& item : cache[x.row]) {
            Y[item.first * N + x.column] += item.second * x.value;
         }
      }
   }
}
