#include <vector>
#include <cmath>
#include <limits>
#include <algorithm>

struct Point {
    double x, y;
};

double distance(Point const& p1, Point const& p2) {
    return std::sqrt(std::pow(p2.x-p1.x, 2) + std::pow(p2.y-p1.y, 2));
}

double stripClosest(std::vector<Point> const& strip, double d) {
    double min = d;
    for (size_t i = 0; i < strip.size(); i++) {
        for (size_t j = i + 1; j < strip.size() && (strip[j].y - strip[i].y) < min; j++) {
            if (distance(strip[i], strip[j]) < min) {
                min = distance(strip[i], strip[j]);
            }
        }
    }
    return min;
}

double closestPairUtil(std::vector<Point> const& points, size_t start, size_t end) {
    if (end - start <= 3) {
        double min = std::numeric_limits<double>::max();
        for (size_t i = start; i < end; i++) {
            for (size_t j = i + 1; j < end; j++) {
                if (distance(points[i], points[j]) < min) {
                    min = distance(points[i], points[j]);
                }
            }
        }
        return min;
    }

    size_t mid = start + (end - start) / 2;
    double dl = closestPairUtil(points, start, mid);
    double dr = closestPairUtil(points, mid, end);
    double d = std::min(dl, dr);

    std::vector<Point> strip;
    for (size_t i = start; i < end; i++) {
        if (std::abs(points[i].x - points[mid].x) < d) {
            strip.push_back(points[i]);
        }
    }

    std::sort(strip.begin(), strip.end(), [](Point const& a, Point const& b) {
        return a.y < b.y;
    });

    return std::min(d, stripClosest(strip, d));
}

double closestPair(std::vector<Point> const& points) {
    if (points.size() < 2) {
        return 0;
    }

    std::vector<Point> sortedPoints = points;
    std::sort(sortedPoints.begin(), sortedPoints.end(), [](Point const& a, Point const& b) {
        return a.x < b.x;
    });

    return closestPairUtil(sortedPoints, 0, points.size());
}
