           [82, 31, 49, 101]]
   output: [[255, 255, 255, 255],
            [255, 147, 0, 255],
            [36, 0, 0, 255],
            [255, 39, 0, 255]]
*/
void convolveKernel(std::vector<int> const& imageIn, std::vector<int> &imageOut, size_t N) {
    for (size_t i = 0; i < N; i++) {
        for (size_t j = 0; j < N; j++){
            int sum = 0;
            for (int k = -1; k < 2; k++) {
                for (int l = -1; l < 2; l++){
                    int x = i + k;
                    int y = j + l;
                    if ((x < 0) || (x >= N) || (y < 0) || (y >= N)) {
                        sum += 0;
                    } else {
                        sum += imageIn[x * N + y] * edgeKernel[k + 1][l + 1];
                    }
                }
            }
            if (sum < 0) {
                imageOut[i * N + j] = 0;
            } else if (sum > 255) {
                imageOut[i * N + j] = 255;
            } else {
                imageOut[i * N + j] = sum;
            }
        }
    }
}

